  task=d->captureConvolutionSurfaceTask(o);task->baseBytes=256*1024*1024;bool rejected=false;try{Document::runConvolutionSurfaceTask(*task,{});}catch(const std::length_error&){rejected=true;}check(rejected&&!task->completed&&d->historySize()==0&&!d->dirty(),"budget atomicity");d->cancelColorAdjustment();
