int run(int argc,wchar_t** argv){check(argc==2,"oracle path");std::ifstream in(std::filesystem::path(argv[1]),std::ios::binary);std::string s{std::istreambuf_iterator<char>(in),{}};auto oracle=JsonObject::Parse(winrt::to_hstring(s));auto rows=oracle.GetNamedArray(L"cases");check(rows.Size()==10080,"oracle coverage");unsigned linked=0;for(unsigned i=0;i<rows.Size();++i){auto row=rows.GetObjectAt(i);context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row);if(i%197==0){RasterHistoryFixture::run(row,true);++linked;}}context="edges";RasterHistoryFixture::edge(rows.GetObjectAt(0));std::cout<<rows.Size()<<" actual legacy convolution results, "<<oracle.GetNamedNumber(L"transactions")<<" legacy transactions, "<<linked<<" linked variants, three encoders and task checks passed\n";return 0;}
int wmain(int argc,wchar_t** argv){const auto hr=RoInitialize(RO_INIT_MULTITHREADED);try{const auto result=run(argc,argv);if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return result;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return 1;}}
